import json
from docx import Document
from docx.text.paragraph import Paragraph
from docx.table import _Cell

input_doc = '/root/offer_letter_template.docx'
output_doc = '/root/offer_letter_filled.docx'

data = json.load(open('/root/employee_data.json'))

# Build placeholder mapping like {{KEY}} -> value
replacements = {f"{{{{{k}}}}}": str(v) for k,v in data.items()}

relocation_yes = str(data.get('RELOCATION_PACKAGE','')).strip().lower() == 'yes'


def replace_in_paragraph(paragraph: Paragraph, replacements):
    if not paragraph.runs:
        if paragraph.text:
            text = paragraph.text
        else:
            return
    # join all run text
    full_text = ''.join(run.text for run in paragraph.runs)
    if not full_text and paragraph.text:
        full_text = paragraph.text
    new_text = full_text
    for ph, val in replacements.items():
        if ph in new_text:
            new_text = new_text.replace(ph, val)
    if new_text != full_text:
        if paragraph.runs:
            paragraph.runs[0].text = new_text
            for run in paragraph.runs[1:]:
                run.text = ''
        else:
            paragraph.add_run(new_text)


def replace_in_container(container):
    # container: Document, _Cell, Header/Footer
    for p in container.paragraphs:
        replace_in_paragraph(p, replacements)
    for table in container.tables:
        for row in table.rows:
            for cell in row.cells:
                replace_in_container(cell)


def remove_paragraph(paragraph: Paragraph):
    p = paragraph._element
    p.getparent().remove(p)
    paragraph._p = paragraph._element = None


def handle_relocation_section(doc: Document):
    # Handle in main document only (headers/footers unlikely)
    if relocation_yes:
        # remove markers only
        for p in doc.paragraphs:
            if '{{IF_RELOCATION}}' in p.text or '{{END_IF_RELOCATION}}' in p.text:
                text = ''.join(run.text for run in p.runs)
                if not text:
                    text = p.text
                text = text.replace('{{IF_RELOCATION}}','').replace('{{END_IF_RELOCATION}}','')
                if p.runs:
                    p.runs[0].text = text
                    for r in p.runs[1:]:
                        r.text = ''
                else:
                    p.add_run(text)
        return

    # relocation is no -> remove content between markers
    in_block = False
    for p in list(doc.paragraphs):
        text = ''.join(run.text for run in p.runs)
        if not text:
            text = p.text
        if '{{IF_RELOCATION}}' in text:
            if '{{END_IF_RELOCATION}}' in text:
                # remove between markers within same paragraph
                before, rest = text.split('{{IF_RELOCATION}}', 1)
                _, after = rest.split('{{END_IF_RELOCATION}}', 1)
                new_text = before + after
                if new_text.strip():
                    if p.runs:
                        p.runs[0].text = new_text
                        for r in p.runs[1:]:
                            r.text = ''
                    else:
                        p.add_run(new_text)
                else:
                    remove_paragraph(p)
                in_block = False
            else:
                # start block: keep text before marker, drop rest
                before = text.split('{{IF_RELOCATION}}',1)[0]
                if before.strip():
                    if p.runs:
                        p.runs[0].text = before
                        for r in p.runs[1:]:
                            r.text = ''
                    else:
                        p.add_run(before)
                else:
                    remove_paragraph(p)
                in_block = True
            continue

        if '{{END_IF_RELOCATION}}' in text:
            # end block: keep text after marker
            after = text.split('{{END_IF_RELOCATION}}',1)[1]
            if after.strip():
                if p.runs:
                    p.runs[0].text = after
                    for r in p.runs[1:]:
                        r.text = ''
                else:
                    p.add_run(after)
            else:
                remove_paragraph(p)
            in_block = False
            continue

        if in_block:
